ALTER TABLE "media_upload_sessions" ADD CONSTRAINT "media_upload_sessions_provider_state_check" CHECK (("media_upload_sessions"."state" in ('initializing', 'recovering') and "media_upload_sessions"."provider_upload_id" is null) or ("media_upload_sessions"."state" = 'aborting' and ("media_upload_sessions"."provider_upload_id" is null or length("media_upload_sessions"."provider_upload_id") between 1 and 1024)) or ("media_upload_sessions"."state" not in ('initializing', 'recovering', 'aborting') and "media_upload_sessions"."provider_upload_id" is not null and length("media_upload_sessions"."provider_upload_id") between 1 and 1024));